import com.fasterxml.jackson.databind.*;import java.nio.charset.*;import java.nio.file.*;import java.sql.*;import java.util.*;import java.util.regex.*;
public final class CompareXueweiguiSchools{
 static final ObjectMapper J=new ObjectMapper();record Db(int id,String name){}
 public static void main(String[]x)throws Exception{String y=Files.readString(Path.of("src/main/resources/application.yml"),StandardCharsets.UTF_8);String u=v(y,"url").replace("192.168.3.5","127.0.0.1");List<Db>db=new ArrayList<>();try(Connection c=DriverManager.getConnection(u,v(y,"username"),v(y,"password"));var s=c.createStatement();var r=s.executeQuery("SELECT id,name FROM school ORDER BY id")){while(r.next())db.add(new Db(r.getInt(1),r.getString(2)));}JsonNode a=J.readTree(Path.of("tmp/xueweigui-schools-20260914.json").toFile()).path("schools");int exact=0,missing=0;StringBuilder out=new StringBuilder("source_id\tsource_name\tmatch_type\ttarget_id\ttarget_name\n");for(JsonNode n:a){String id=n.path("list").path("id").asText(),name=n.path("list").path("name").asText();List<Db>m=db.stream().filter(d->norm(d.name).equals(norm(name))).toList();if(m.size()==1){exact++;out.append(id).append('\t').append(name).append("\texact\t").append(m.get(0).id).append('\t').append(m.get(0).name).append('\n');}else{missing++;Db best=db.stream().min(Comparator.comparingInt(d->lev(norm(d.name),norm(name)))).orElseThrow();int dist=lev(norm(best.name),norm(name));out.append(id).append('\t').append(name).append("\tunmatched(best_distance=").append(dist).append(")\t").append(best.id).append('\t').append(best.name).append('\n');}}Files.writeString(Path.of("tmp/xueweigui-school-match.tsv"),out.toString(),StandardCharsets.UTF_8);System.out.printf("source=%d db=%d exact=%d unmatched=%d report=tmp/xueweigui-school-match.tsv%n",a.size(),db.size(),exact,missing);}
 static String norm(String s){return s.replaceFirst("^上海市?","").replaceAll("[\\s·•()（）《》【】\\-—_/]","").toLowerCase();}
 static int lev(String a,String b){int[]p=new int[b.length()+1],q=new int[b.length()+1];for(int j=0;j<=b.length();j++)p[j]=j;for(int i=1;i<=a.length();i++){q[0]=i;for(int j=1;j<=b.length();j++)q[j]=Math.min(Math.min(q[j-1]+1,p[j]+1),p[j-1]+(a.charAt(i-1)==b.charAt(j-1)?0:1));int[]t=p;p=q;q=t;}return p[b.length()];}
 static String v(String y,String k){var m=Pattern.compile("(?m)^\\s*"+k+":\\s*([^\\r\\n#]+)").matcher(y);if(!m.find())throw new IllegalStateException(k);String z=m.group(1).trim();var p=Pattern.compile("\\$\\{([^:}]+)(?::([^}]*))?}").matcher(z);if(!p.matches())return z;String e=System.getenv(p.group(1));return e!=null&&!e.isBlank()?e:p.group(2);}
}
